items.copy:
$names = 'agy','codex','claude'
$guess = @{
  agy    = @("$env:LOCALAPPDATA\agy\bin")
  codex  = @("$env:LOCALAPPDATA\Programs\OpenAI\Codex\bin", "$env:USERPROFILE\.codex\bin")
  claude = @("$env:USERPROFILE\.local\bin")
}
$roots = @($env:LOCALAPPDATA, $env:APPDATA, $env:USERPROFILE) | Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique
$add = @()
foreach ($n in $names) {
  if (Get-Command $n -ErrorAction SilentlyContinue) { Write-Host "OK   $n - 이미 PATH 에 있습니다"; continue }
  $dir = $null
  foreach ($g in $guess[$n]) { if (Test-Path (Join-Path $g "$n.exe")) { $dir = $g; break } }
  if (-not $dir) {
    foreach ($r in $roots) {
      $hit = Get-ChildItem -Path $r -Filter "$n.exe" -Recurse -File -Depth 5 -ErrorAction SilentlyContinue | Select-Object -First 1
      if ($hit) { $dir = $hit.DirectoryName; break }
    }
  }
  if ($dir) { Write-Host "FIND $n - $dir"; $add += $dir }
  else      { Write-Host "MISS $n - 찾지 못했습니다. 설치부터 다시 하세요" }
}
$add = $add | Select-Object -Unique
if ($add.Count -eq 0) { Write-Host "추가할 경로가 없습니다"; return }
$userPath = [Environment]::GetEnvironmentVariable('Path','User')
$have = @($userPath -split ';' | Where-Object { $_ })
$new = @($add | Where-Object { $have -notcontains $_ })
if ($new.Count -eq 0) { Write-Host "이미 모두 등록돼 있습니다"; return }
[Environment]::SetEnvironmentVariable('Path', (($have + $new) -join ';'), 'User')
Write-Host ("ADDED " + ($new -join ' | '))
